const tutoria = $('Nueva tutoria agendada').first().json;
const estItems = $('Buscar datos estudiante').all();
const tutItems = $('Buscar datos tutor').all();

const est = estItems.length ? estItems[0].json : {};
const tut = tutItems.length ? tutItems[0].json : {};

const nombreEstudiante = est.nombre || tutoria.id_estudiante || 'Desconocido';
const correoEstudiante = est.correo || '';
const nombreTutor = tut.nombre || tutoria.id_tutor || 'Sin asignar';

const asunto = `Nueva tutoria agendada: ${tutoria.materia} - ${tutoria.fecha}`;

const cuerpo = `Se registro una nueva tutoria.\n\n` +
  `Estudiante: ${nombreEstudiante} (${tutoria.id_estudiante})\n` +
  (correoEstudiante ? `Correo: ${correoEstudiante}\n` : '') +
  `Materia: ${tutoria.materia}\n` +
  `Fecha: ${tutoria.fecha}\n` +
  `Hora: ${tutoria.hora}\n` +
  `Tutor: ${nombreTutor}\n` +
  `ID tutoria: ${tutoria.id_tutoria}\n` +
  `Estado: ${tutoria.estado}`;

return [{ json: { asunto, cuerpo } }];

