        Se ha registrado una nueva tutoría en el sistema.
      </p>

      <table class="details-table">
        <tr>
          <td class="label">Estudiante</td>
          <td>{{estudiante_nombre}} ({{estudiante_id}})</td>
        </tr>
        <tr>
          <td class="label">Correo</td>
          <td><a href="mailto:{{estudiante_correo}}" style="color: #3182ce; text-decoration: none;">{{estudiante_correo}}</a></td>
