        <tr>
          <td class="label">Materia</td>
          <td>{{materia}}</td>
        </tr>
        <tr>
          <td class="label">Fecha y Hora</td>
          <td>{{fecha}} - {{hora}}</td>
        </tr>
        <tr>
          <td class="label">Tutor</td>
          <td>{{tutor_nombre}}</td>
        </tr>
        <tr>
          <td class="label">ID Tutoría</td>
          <td><strong>{{id_tutoria}}</strong></td>
        </tr>
        <tr>
          <td class="label">Estado</td>
          <td><span class="status-badge">{{estado}}</span></td>
        </tr>
      </table>
    </div>

    <div class="footer">
      Este correo fue enviado automáticamente por el sistema de gestión.
    </div>
  </div>

</body>
